const modifiedAfter = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
const base = `modified_after=${encodeURIComponent(modifiedAfter)}&completed=true&limit=100&field=audit_id&field=modified_at&field=template_id`;
const templates = [
  'template_7dbbb416041a44459216a2a0ba02bb10',
  'template_0a8a57e828e746f782b2659da47f398d'
];
return templates.map(id => ({
  json: {
    templateId: id,
    searchUrl: `https://api.safetyculture.io/audits/search?template=${id}&${base}`
  }
}));

const allItems = [];
for (const item of $input.all()) {
  const audits = item.json.audits || [];
  const sorted = [...audits]
    .sort((a, b) => (b.modified_at || '').localeCompare(a.modified_at || ''))
    .slice(0, 20);
  for (const audit of sorted) {
    if (audit.audit_id) allItems.push({ json: { audit_id: audit.audit_id } });
  }
}
const seen = new Set();
return allItems.filter(i => {
  if (seen.has(i.json.audit_id)) return false;
  seen.add(i.json.audit_id);
  return true;
});

const inspection = $input.item.json;
const auditData    = inspection.audit_data    || {};
const templateData = inspection.template_data || {};
const items        = inspection.items         || [];

const site         = auditData.site?.name                  || 'Unknown Site';
const supervisor   = auditData.authorship?.owner           || 'Unknown';
const dateStr      = auditData.date_started                || '';
const completed    = auditData.date_completed;
const score        = auditData.score        ?? '';
const total        = auditData.total_score  ?? '';
const pct          = auditData.score_percentage ?? '';
const jobNo        = auditData.reference_id || (inspection.audit_id || '').substring(0, 8);
const templateName = templateData.metadata?.name || 'Unknown Template';

let dateFormatted = dateStr;
try {
  dateFormatted = new Date(dateStr).toLocaleDateString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
} catch(e) {}

const lines = [];
for (const item of items) {
  const label    = (item.label            || '').trim();
  if (!label) continue;
  const responses = item.responses        || {};
  const selected  = responses.selected   || [];
  const textResp  = (responses.text      || '').trim();
  const note      = (item.note           || '').trim();
  const status    = selected[0]?.label?.trim() || '';
  let line = label;
  if (status)   line += `: ${status}`;
  if (textResp) line += ` | text: ${textResp}`;
  if (note)     line += ` | note: ${note}`;
  lines.push(line);
}

const fullText = [
  `Template: ${templateName}`,
  `Site: ${site}`,
  `Date: ${dateFormatted}`,
  `Supervisor: ${supervisor}`,
  `Score: ${score} / ${total} (${pct}%)`,
  `Signed Off: ${completed ? 'Yes' : 'No'}`,
  '',
  'EQUIPMENT / ITEMS:',
  ...lines
].join('\n');

return [{ json: {
  audit_id:      inspection.audit_id || '',
  site,
  job_no:        jobNo,
  supervisor,
  date:          dateFormatted,
  signed:        Boolean(completed),
  template_name: templateName,
  full_text:     fullText
}}];

const claudeResp   = $input.item.json;
const claudeText   = claudeResp.content?.[0]?.text || '{}';
const inspData     = $('Prepare Claude Request').item.json;

let analysis = {};
try {
  let raw = claudeText.trim();
  if (raw.startsWith('```')) {
    raw = raw.split('```')[1];
    if (raw.startsWith('json')) raw = raw.substring(4);
  }
  analysis = JSON.parse(raw.trim());
} catch(e) {
  analysis = {
    puwer:'', loler:'', site_sup:'', xcavator:'', dumper:'',
    roller:'', telehand:'', havs:'', toolbox:'', rams:'',
    note: 'Analysis parse error',
    note_severity: 'warning',
    warning_cells: []
  };
}

return [{ json: {
  site:          inspData.site,
  job_no:        inspData.job_no,
  supervisor:    inspData.supervisor,
  date:          inspData.date,
  signed:        inspData.signed,
  template_name: inspData.template_name,
  analysis
}}];

// ── Requires exceljs ──────────────────────────────────────────────
// In your n8n environment add: NODE_FUNCTION_ALLOW_EXTERNAL=exceljs
// Then: npm install exceljs  (in your n8n directory)
// ──────────────────────────────────────────────────────────────────
const ExcelJS = require('exceljs');

const results = $input.item.json.results || [];
const today   = new Date().toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'numeric'});
const dateSlug = new Date().toISOString().split('T')[0];

const wb = new ExcelJS.Workbook();
const ws = wb.addWorksheet(today);

const COLS = [
  { header: 'SITE',       key: 'site',       width: 22 },
  { header: 'JOB NO',     key: 'job_no',     width: 9  },
  { header: 'PUWER',      key: 'puwer',      width: 8  },
  { header: 'LOLER',      key: 'loler',      width: 8  },
  { header: 'SITE SUP',   key: 'site_sup',   width: 9  },
  { header: 'XCAVATOR',   key: 'xcavator',   width: 10 },
  { header: 'DUMPER',     key: 'dumper',     width: 9  },
  { header: 'ROLLER',     key: 'roller',     width: 9  },
  { header: 'TELEHAND',   key: 'telehand',   width: 11 },
  { header: 'HAVS',       key: 'havs',       width: 8  },
  { header: 'TOOLBOX',    key: 'toolbox',    width: 10 },
  { header: 'RAMS',       key: 'rams',       width: 8  },
  { header: 'SUPERVISOR', key: 'supervisor', width: 16 },
  { header: 'NOTES',      key: 'notes',      width: 45 },
];
ws.columns = COLS;

const COL_KEY = {
  'PUWER':    'puwer',  'LOLER':   'loler',    'SITE SUP': 'site_sup',
  'XCAVATOR': 'xcavator', 'DUMPER': 'dumper',  'ROLLER':   'roller',
  'TELEHAND': 'telehand', 'HAVS':  'havs',     'TOOLBOX':  'toolbox',
  'RAMS':     'rams'
};

const BORDER = {
  top:{style:'thin'}, left:{style:'thin'},
  bottom:{style:'thin'}, right:{style:'thin'}
};

// ── Header row ──────────────────────────────────────────────────────
const hdrRow = ws.getRow(1);
hdrRow.height = 22;
hdrRow.eachCell(cell => {
  cell.fill      = { type:'pattern', pattern:'solid',
                     fgColor:{ argb: cell.value === 'RAMS' ? 'FFFFFF00' : 'FFF4A460' } };
  cell.font      = { bold: true };
  cell.alignment = { horizontal:'center', vertical:'middle', wrapText:true };
  cell.border    = BORDER;
});

// ── Data rows ───────────────────────────────────────────────────────
for (const r of results) {
  const a    = r.analysis || {};
  const warn = new Set(a.warning_cells || []);
  const note = a.note          || '';
  const sev  = a.note_severity || 'none';

  const row = ws.addRow([
    r.site,       r.job_no,
    a.puwer,      a.loler,    a.site_sup,
    a.xcavator,   a.dumper,   a.roller,   a.telehand,
    a.havs,       a.toolbox,  a.rams,
    r.supervisor, note
  ]);
  row.height = 18;

  row.eachCell((cell, col) => {
    const hdr = COLS[col - 1].header;
    const key = COL_KEY[hdr];
    cell.border    = BORDER;
    cell.alignment = { horizontal:'center', vertical:'middle', wrapText:true };

    if (hdr === 'NOTES') {
      if (sev === 'critical') {
        cell.fill      = { type:'pattern', pattern:'solid', fgColor:{ argb:'FFFF0000' } };
        cell.font      = { bold:true, color:{ argb:'FFFFFFFF' } };
        cell.alignment = { horizontal:'left', vertical:'middle', wrapText:true };
      } else if (sev === 'warning') {
        cell.fill      = { type:'pattern', pattern:'solid', fgColor:{ argb:'FFFFFF00' } };
        cell.alignment = { horizontal:'left', vertical:'middle', wrapText:true };
      }
    } else if (key && warn.has(key)) {
      cell.fill = { type:'pattern', pattern:'solid', fgColor:{ argb:'FFFFFF00' } };
    }
  });
}

ws.views = [{ state:'frozen', ySplit:1 }];

// ── Serialise ───────────────────────────────────────────────────────
const buf      = await wb.xlsx.writeBuffer();
const b64      = Buffer.from(buf).toString('base64');
const hasCrit  = results.some(r => r.analysis?.note_severity === 'critical');
const subject  = hasCrit
  ? `⚠️ Ashvale Inspections — Action Required — ${today}`
  : `✅ Ashvale Inspections — All Clear — ${today}`;
const body     = [
  `Ashvale Civil Engineering — Daily Inspection Report`,
  `Date: ${today}`,
  `Inspections processed: ${results.length}`,
  '',
  hasCrit
    ? '⚠️  One or more sites require action — see red rows in the spreadsheet.'
    : '✅  All inspections clear.',
  '',
  'Please find the Excel report attached.'
].join('\n');

return [{
  json: {
    subject,
    body,
    filename: `Ashvale_Inspections_${dateSlug}.xlsx`
  },
  binary: {
    attachment: {
      data:     b64,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: `Ashvale_Inspections_${dateSlug}.xlsx`
    }
  }
}];
